from test_bufftap import test, ROOT
RECORD=(ROOT/'tests/nearby_preview_record.lua').read_text(encoding='utf-8-sig')
SETUP="""
local B=BuffTap; local make=CreateFrame
CreateFrame=function(...) local f=make(...); local expiry=select(2,...)=='BuffTapCombatExpiry'; f.SetFrameStrata=function(s,v) assert(not combat or expiry); s.actualStrata=v end; return f end
B.button=nil; B:CreateButton(); B:CreateCampReminder(); B:CreateSupplyBadge(); B:CreateNearbyWindow(); B:CreateQueueButton(1); B:CreateCombatExpiryFrame()
B.manualConsumableHolder=CreateFrame('Frame',nil,UIParent)
B:ApplyGameplayLayers()
"""
test('Gameplay overlays default LOW and settings dialogs retain their layer',SETUP+"for _,f in ipairs({B.button,B.campReminderIcon,B.supplyBadge,B.nearbyFrame,B.queueButtons[1],B.combatExpiryFrame,B.manualConsumableHolder}) do assert(f.actualStrata=='LOW') end; B:Options(); assert(B.options.actualStrata=='DIALOG')")
for key,kind in [('reminderOnTop','buff'),('campOnTop','camp'),('supplyOnTop','supply'),('nearbyOnTop','nearby')]:
 test('Independent overlay preference '+key,SETUP+"B.db."+key+"=true; B:ApplyGameplayLayers(); assert(B:GameplayStrata('"+kind+"')=='DIALOG'); local frames={buff={B.button,B.queueButtons[1],B.combatExpiryFrame,B.manualConsumableHolder},camp={B.campReminderIcon},supply={B.supplyBadge},nearby={B.nearbyFrame}}; for k,list in pairs(frames) do for _,f in ipairs(list) do assert(f.actualStrata==(k=='"+kind+"' and 'DIALOG' or 'LOW')) end end; B.db."+key+"=false; B:ApplyGameplayLayers(); for _,list in pairs(frames) do for _,f in ipairs(list) do assert(f.actualStrata=='LOW') end end")
test('Combat defers layer writes until normal refresh',SETUP+"combat=true; B.db.reminderOnTop=true; B:ApplyGameplayLayers(); B:Refresh(); assert(B.button.actualStrata=='LOW' and B.queueButtons[1].actualStrata=='LOW'); combat=false; safety('ready'); B:Refresh(); assert(B.button.actualStrata=='DIALOG' and B.queueButtons[1].actualStrata=='DIALOG')")
test('Layer preferences survive profile export import and copy',SETUP+"B.db.reminderOnTop=true; B.db.campOnTop=true; B.db.supplyOnTop=true; B:CreateSettingsProfile('Layers',true); assert(B.db.reminderOnTop and B.db.campOnTop and B.db.supplyOnTop); local export=B:ExportSettings(false); B.db.reminderOnTop=false; B.db.campOnTop=false; B.db.supplyOnTop=false; assert(B:ImportSettings(export)); assert(B.db.reminderOnTop and B.db.campOnTop and B.db.supplyOnTop); B:ApplyGameplayLayers(); assert(B.button.actualStrata=='DIALOG')")
test('Customization layer switches share compact placement and real callbacks',RECORD+"local B=BuffTap; B:Options(); local f=B.options; for key,c in pairs(f.overlayLayers) do assert(c.__draw.points[1][2]==230 and c.__draw.points[1][3]==-554); c:SetChecked(true); c.scripts.OnClick(c); assert(B.db[key]==true); c:SetChecked(false); c.scripts.OnClick(c); assert(B.db[key]==false) end; assert(f.overlayLayers.reminderOnTop and f.overlayLayers.campOnTop and f.overlayLayers.supplyOnTop); assert(f.detachConsumables.__draw.points[1][3]==-554); assert(f.nearbyOnTop.__draw.points[1][2]==230)")

test('Late-created queue and nonsecure combat warning inherit reminder layer',SETUP+"B.db.reminderOnTop=true; local q=B:CreateQueueButton(2); assert(q.actualStrata=='DIALOG'); B.combatExpiryFrame=nil; combat=true; local f=B:CreateCombatExpiryFrame(); assert(f.actualStrata=='DIALOG'); B:SetGameplayLayer(B.button,'buff'); assert(B.button.actualStrata=='LOW')")
test('Profile switch restores layers and preserves existing Nearby top preference',SETUP+"local original=B.profileDB:GetCurrentProfile(); B.db.nearbyOnTop=true; B.db.reminderOnTop=true; B:CreateSettingsProfile('LowLayers',false); B:ApplyGameplayLayers(); assert(B.button.actualStrata=='LOW'); B:SelectSettingsProfile(original); B:ApplyGameplayLayers(); assert(B.button.actualStrata=='DIALOG' and B.nearbyFrame.actualStrata=='DIALOG')")
